const std = @import("std");

pub fn build(b: *std.Build) void {
    const target = b.standardTargetOptions(.{});
    const optimize = b.standardOptimizeOption(.{});

    const root_module = b.createModule(.{
        .root_source_file = b.path("src/main.zig"),
        .target = target,
        .optimize = optimize,
    });

    const exe = b.addExecutable(.{ .name = "kvhttp", .root_module = root_module });
    b.installArtifact(exe);

    const run_cmd = b.addRunArtifact(exe);
    run_cmd.step.dependOn(b.getInstallStep());
    if (b.args) |args| run_cmd.addArgs(args);
    b.step("run", "Run the server").dependOn(&run_cmd.step);

    const tests = b.addTest(.{ .root_module = root_module });
    b.step("test", "Run unit tests").dependOn(&b.addRunArtifact(tests).step);
}

//! Thread-safe in-memory key/value store.
//!
//! Values are reference counted so readers can drop the lock before a
//! (possibly large) value is written to the network.

const KvStore = @This();

const std = @import("std");
const Allocator = std.mem.Allocator;
const Io = std.Io;

gpa: Allocator,
lock: Io.RwLock = .init,
map: std.StringHashMapUnmanaged(*Value) = .empty,

/// An immutable, reference-counted stored value.
pub const Value = struct {
    refs: std.atomic.Value(u32),
    bytes: []const u8,

    /// Takes ownership of `bytes` on success.
    fn create(gpa: Allocator, bytes: []const u8) Allocator.Error!*Value {
        const value = try gpa.create(Value);
        value.* = .{ .refs = .init(1), .bytes = bytes };
        return value;
    }

    pub fn retain(value: *Value) void {
        _ = value.refs.fetchAdd(1, .monotonic);
    }

    /// Drops one reference, freeing the value when it was the last one.
    pub fn release(value: *Value, gpa: Allocator) void {
        if (value.refs.fetchSub(1, .acq_rel) != 1) return;
        gpa.free(value.bytes);
        gpa.destroy(value);
    }
};

pub fn init(gpa: Allocator) KvStore {
    return .{ .gpa = gpa };
}

pub fn deinit(store: *KvStore) void {
    var it = store.map.iterator();
    while (it.next()) |entry| {
        store.gpa.free(entry.key_ptr.*);
        entry.value_ptr.*.release(store.gpa);
    }
    store.map.deinit(store.gpa);
    store.* = undefined;
}

/// Stores `bytes` under `key`. `bytes` must be allocated with the store's
/// allocator; ownership passes to the store on success and stays with the
/// caller on error. Returns true if the key was new, false if it replaced a
/// value.
pub fn put(store: *KvStore, io: Io, key: []const u8, bytes: []const u8) Allocator.Error!bool {
    const value = try Value.create(store.gpa, bytes);
    errdefer store.gpa.destroy(value);

    const replaced: ?*Value = replaced: {
        store.lock.lockUncancelable(io);
        defer store.lock.unlock(io);

        const gop = try store.map.getOrPut(store.gpa, key);
        if (gop.found_existing) {
            const old = gop.value_ptr.*;
            gop.value_ptr.* = value;
            break :replaced old;
        }
        gop.key_ptr.* = store.gpa.dupe(u8, key) catch |err| {
            store.map.removeByPtr(gop.key_ptr);
            return err;
        };
        gop.value_ptr.* = value;
        break :replaced null;
    };

    // Free the old value outside the critical section.
    if (replaced) |old| old.release(store.gpa);
    return replaced == null;
}

/// Returns the value stored under `key`, or null. The caller owns one
/// reference and must call `Value.release`.
pub fn get(store: *KvStore, io: Io, key: []const u8) ?*Value {
    store.lock.lockSharedUncancelable(io);
    defer store.lock.unlockShared(io);

    const value = store.map.get(key) orelse return null;
    value.retain();
    return value;
}

/// Removes `key`. Returns true if it was present.
pub fn remove(store: *KvStore, io: Io, key: []const u8) bool {
    const removed = removed: {
        store.lock.lockUncancelable(io);
        defer store.lock.unlock(io);
        break :removed store.map.fetchRemove(key) orelse return false;
    };
    store.gpa.free(removed.key);
    removed.value.release(store.gpa);
    return true;
}

/// Returns a copy of every key in ascending byte-wise order. All memory is
/// allocated with `arena`; the caller frees it by resetting the arena.
pub fn sortedKeys(store: *KvStore, io: Io, arena: Allocator) Allocator.Error![]const []const u8 {
    const keys = keys: {
        store.lock.lockSharedUncancelable(io);
        defer store.lock.unlockShared(io);

        const keys = try arena.alloc([]const u8, store.map.count());
        var it = store.map.keyIterator();
        var i: usize = 0;
        while (it.next()) |key| : (i += 1) keys[i] = try arena.dupe(u8, key.*);
        break :keys keys;
    };

    std.mem.sortUnstable([]const u8, keys, {}, lessThan);
    return keys;
}

fn lessThan(_: void, a: []const u8, b: []const u8) bool {
    return std.mem.order(u8, a, b) == .lt;
}

test "put, get, replace, remove" {
    const gpa = std.testing.allocator;
    const io = std.testing.io;
    var store: KvStore = .init(gpa);
    defer store.deinit();

    try std.testing.expect(try store.put(io, "a", try gpa.dupe(u8, "one")));
    try std.testing.expect(!try store.put(io, "a", try gpa.dupe(u8, "two")));

    const value = store.get(io, "a").?;
    defer value.release(gpa);
    try std.testing.expectEqualStrings("two", value.bytes);

    // A reader's reference outlives removal.
    try std.testing.expect(store.remove(io, "a"));
    try std.testing.expect(!store.remove(io, "a"));
    try std.testing.expect(store.get(io, "a") == null);
    try std.testing.expectEqualStrings("two", value.bytes);
}

test "sortedKeys" {
    const gpa = std.testing.allocator;
    const io = std.testing.io;
    var store: KvStore = .init(gpa);
    defer store.deinit();

    for ([_][]const u8{ "b", "a", "_", "B", "c" }) |key| {
        _ = try store.put(io, key, try gpa.dupe(u8, key));
    }

    var arena: std.heap.ArenaAllocator = .init(gpa);
    defer arena.deinit();
    const keys = try store.sortedKeys(io, arena.allocator());
    const expected = [_][]const u8{ "B", "_", "a", "b", "c" };
    try std.testing.expectEqual(expected.len, keys.len);
    for (expected, keys) |want, got| try std.testing.expectEqualStrings(want, got);
}

//! Maps requests onto the key/value API described in SPEC.md.

const Router = @This();

const std = @import("std");
const Allocator = std.mem.Allocator;
const Io = std.Io;

const http = @import("http.zig");
const KvStore = @import("KvStore.zig");

store: *KvStore,

const kv_prefix = "/kv/";
const max_key_len = 64;

pub const Reply = struct {
    response: http.Response,
    /// Stored value backing `response.body`, if any. The holder must call
    /// `release` once the response has been written.
    value: ?*KvStore.Value = null,

    fn of(response: http.Response) Reply {
        return .{ .response = response };
    }

    pub fn release(reply: Reply, gpa: Allocator) void {
        if (reply.value) |value| value.release(gpa);
    }
};

/// Handles `request`. Temporary allocations come from `arena`, which must
/// outlive the reply. On a successful PUT the body is moved into the store
/// and `request.body` is left empty.
pub fn handle(router: Router, io: Io, arena: Allocator, request: *http.Request) Allocator.Error!Reply {
    const path = request.target;
    const method = request.method;

    if (std.mem.eql(u8, path, "/health")) {
        if (!std.mem.eql(u8, method, "GET")) return methodNotAllowed("GET");
        return .of(.text(.ok, "ok"));
    }
    if (std.mem.eql(u8, path, "/kv")) {
        if (!std.mem.eql(u8, method, "GET")) return methodNotAllowed("GET");
        return router.listKeys(io, arena);
    }
    if (std.mem.startsWith(u8, path, kv_prefix)) {
        const key = path[kv_prefix.len..];
        if (!isValidKey(key)) return .of(.empty(.bad_request));
        return router.handleKey(io, request, key);
    }
    return .of(.empty(.not_found));
}

fn handleKey(router: Router, io: Io, request: *http.Request, key: []const u8) Allocator.Error!Reply {
    const store = router.store;
    const method = request.method;

    if (std.mem.eql(u8, method, "GET")) {
        const value = store.get(io, key) orelse return .of(.empty(.not_found));
        return .{
            .response = .{ .status = .ok, .content_type = "application/octet-stream", .body = value.bytes },
            .value = value,
        };
    }
    if (std.mem.eql(u8, method, "PUT")) {
        const created = try store.put(io, key, request.body);
        request.body = &.{};
        return .of(.empty(if (created) .created else .ok));
    }
    if (std.mem.eql(u8, method, "DELETE")) {
        return .of(.empty(if (store.remove(io, key)) .no_content else .not_found));
    }
    return methodNotAllowed("GET, PUT, DELETE");
}

fn listKeys(router: Router, io: Io, arena: Allocator) Allocator.Error!Reply {
    const keys = try router.store.sortedKeys(io, arena);

    // Keys are restricted to [A-Za-z0-9_-], so no JSON escaping is needed.
    var len: usize = 2 + (keys.len -| 1); // brackets and commas
    for (keys) |key| len += key.len + 2;

    var json: std.ArrayList(u8) = try .initCapacity(arena, len);
    json.appendAssumeCapacity('[');
    for (keys, 0..) |key, i| {
        if (i != 0) json.appendAssumeCapacity(',');
        json.appendAssumeCapacity('"');
        json.appendSliceAssumeCapacity(key);
        json.appendAssumeCapacity('"');
    }
    json.appendAssumeCapacity(']');

    return .of(.{ .status = .ok, .content_type = "application/json", .body = json.items });
}

fn methodNotAllowed(allow: []const u8) Reply {
    return .of(.{ .status = .method_not_allowed, .allow = allow });
}

/// A key matches `[A-Za-z0-9_-]{1,64}`.
pub fn isValidKey(key: []const u8) bool {
    if (key.len == 0 or key.len > max_key_len) return false;
    for (key) |c| switch (c) {
        'A'...'Z', 'a'...'z', '0'...'9', '_', '-' => {},
        else => return false,
    };
    return true;
}

// ---------------------------------------------------------------- tests

const testing = std.testing;

test isValidKey {
    try testing.expect(isValidKey("a"));
    try testing.expect(isValidKey("A-z_09"));
    try testing.expect(isValidKey("k" ** 64));
    try testing.expect(!isValidKey(""));
    try testing.expect(!isValidKey("k" ** 65));
    try testing.expect(!isValidKey("a/b"));
    try testing.expect(!isValidKey("bad.key"));
    try testing.expect(!isValidKey("%41"));
}

fn expectStatus(router: Router, status: http.Status, method: []const u8, target: []const u8, body: []const u8) !void {
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    var request: http.Request = .{ .method = method, .target = target, .body = try testing.allocator.dupe(u8, body) };
    defer testing.allocator.free(request.body);
    const reply = try router.handle(testing.io, arena.allocator(), &request);
    defer reply.release(testing.allocator);
    try testing.expectEqual(status, reply.response.status);
}

test "routes" {
    var store: KvStore = .init(testing.allocator);
    defer store.deinit();
    const router: Router = .{ .store = &store };

    try expectStatus(router, .ok, "GET", "/health", "");
    try expectStatus(router, .method_not_allowed, "POST", "/health", "");
    try expectStatus(router, .not_found, "GET", "/nope", "");
    try expectStatus(router, .bad_request, "GET", "/kv/", "");
    try expectStatus(router, .bad_request, "GET", "/kv/a/b", "");
    try expectStatus(router, .created, "PUT", "/kv/a", "1");
    try expectStatus(router, .ok, "PUT", "/kv/a", "2");
    try expectStatus(router, .ok, "GET", "/kv/a", "");
    try expectStatus(router, .method_not_allowed, "PATCH", "/kv/a", "");
    try expectStatus(router, .method_not_allowed, "DELETE", "/kv", "");
    try expectStatus(router, .no_content, "DELETE", "/kv/a", "");
    try expectStatus(router, .not_found, "DELETE", "/kv/a", "");
    try expectStatus(router, .not_found, "GET", "/kv/a", "");
}

test "list keys as JSON" {
    var store: KvStore = .init(testing.allocator);
    defer store.deinit();
    const router: Router = .{ .store = &store };

    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    var request: http.Request = .{ .method = "GET", .target = "/kv", .body = &.{} };

    try testing.expectEqualStrings("[]", (try router.handle(testing.io, arena.allocator(), &request)).response.body);
    _ = try store.put(testing.io, "b", try testing.allocator.dupe(u8, "2"));
    _ = try store.put(testing.io, "a", try testing.allocator.dupe(u8, "1"));
    try testing.expectEqualStrings("[\"a\",\"b\"]", (try router.handle(testing.io, arena.allocator(), &request)).response.body);
}

//! Minimal HTTP/1.1 request reader and response writer: one request per
//! connection, `Content-Length` bodies only.

const std = @import("std");
const Allocator = std.mem.Allocator;
const Io = std.Io;

pub const Status = std.http.Status;

/// Limits applied while reading a request.
pub const Limits = struct {
    max_header_bytes: usize = 64 * 1024,
    max_body_bytes: usize = 1024 * 1024,

    /// Smallest reader buffer that can hold a maximal request head.
    pub fn readBufferLen(limits: Limits) usize {
        return limits.max_header_bytes + header_end.len;
    }
};

pub const Request = struct {
    method: []const u8,
    target: []const u8,
    /// Owned by the allocator passed to `readRequest` as `body_allocator`.
    body: []u8,
};

pub const ReadResult = union(enum) {
    request: Request,
    /// The request was malformed or exceeded a limit; reply with this status.
    reject: Status,
    /// The peer went away (or timed out) before sending a full request.
    closed,
};

pub const Response = struct {
    status: Status,
    content_type: ?[]const u8 = null,
    /// Value of the `Allow` header, for 405 responses.
    allow: ?[]const u8 = null,
    body: []const u8 = "",

    pub fn empty(status: Status) Response {
        return .{ .status = status };
    }

    pub fn text(status: Status, body: []const u8) Response {
        return .{ .status = status, .content_type = "text/plain; charset=utf-8", .body = body };
    }
};

const crlf = "\r\n";
const header_end = "\r\n\r\n";

/// Reads one request from `reader`, whose buffer must be at least
/// `limits.readBufferLen()` bytes. Method and target are copied into `arena`;
/// the body is allocated with `body_allocator`.
pub fn readRequest(
    reader: *Io.Reader,
    arena: Allocator,
    body_allocator: Allocator,
    limits: Limits,
) Allocator.Error!ReadResult {
    std.debug.assert(reader.buffer.len >= limits.readBufferLen());

    var search_from: usize = 0;
    const head_len = while (true) {
        const buffered = reader.buffered();
        if (std.mem.indexOfPos(u8, buffered, search_from, header_end)) |end| break end;
        if (buffered.len > limits.max_header_bytes) return .{ .reject = .request_header_fields_too_large };
        search_from = buffered.len -| (header_end.len - 1);
        reader.fillMore() catch return .closed;
    };
    if (head_len > limits.max_header_bytes) return .{ .reject = .request_header_fields_too_large };

    const head = reader.buffered()[0..head_len];
    var lines = std.mem.splitSequence(u8, head, crlf);

    // request-line = method SP request-target SP HTTP-version
    const request_line = lines.first();
    const sp1 = std.mem.indexOfScalar(u8, request_line, ' ') orelse return .{ .reject = .bad_request };
    const sp2 = std.mem.indexOfScalarPos(u8, request_line, sp1 + 1, ' ') orelse return .{ .reject = .bad_request };
    if (sp1 == 0 or sp2 == sp1 + 1) return .{ .reject = .bad_request };
    const version = request_line[sp2 + 1 ..];
    if (!std.mem.startsWith(u8, version, "HTTP/1.")) {
        return .{ .reject = if (std.mem.startsWith(u8, version, "HTTP/")) .http_version_not_supported else .bad_request };
    }

    var content_length: ?usize = null;
    while (lines.next()) |line| {
        const colon = std.mem.indexOfScalar(u8, line, ':') orelse return .{ .reject = .bad_request };
        if (colon == 0) return .{ .reject = .bad_request };
        const name = line[0..colon];
        const value = std.mem.trim(u8, line[colon + 1 ..], " \t");

        if (std.ascii.eqlIgnoreCase(name, "Content-Length")) {
            const len = parseContentLength(value) orelse return .{ .reject = .bad_request };
            if (content_length) |prev| if (prev != len) return .{ .reject = .bad_request };
            content_length = len;
        } else if (std.ascii.eqlIgnoreCase(name, "Transfer-Encoding")) {
            return .{ .reject = .not_implemented };
        }
    }

    // Copy what we keep out of the reader buffer before reading the body,
    // which may rebase that buffer.
    const method = try arena.dupe(u8, request_line[0..sp1]);
    const target = try arena.dupe(u8, request_line[sp1 + 1 .. sp2]);
    reader.toss(head_len + header_end.len);

    const length = content_length orelse 0;
    if (length > limits.max_body_bytes) {
        // Consume the body so the peer sees a clean close rather than a reset.
        reader.discardAll(length) catch {};
        return .{ .reject = .payload_too_large };
    }

    const body = try body_allocator.alloc(u8, length);
    reader.readSliceAll(body) catch {
        // Truncated body: the peer is gone.
        body_allocator.free(body);
        return .closed;
    };

    return .{ .request = .{ .method = method, .target = target, .body = body } };
}

/// Parses a non-empty run of ASCII digits (no sign, no separators).
fn parseContentLength(value: []const u8) ?usize {
    if (value.len == 0) return null;
    for (value) |c| if (!std.ascii.isDigit(c)) return null;
    return std.fmt.parseUnsigned(usize, value, 10) catch null;
}

/// Writes the full response, always with `Connection: close`.
pub fn writeResponse(writer: *Io.Writer, response: Response) Io.Writer.Error!void {
    const status = response.status;
    try writer.print("HTTP/1.1 {d} {s}\r\n", .{ @intFromEnum(status), status.phrase() orelse "Unknown" });
    if (response.content_type) |value| try writer.print("Content-Type: {s}\r\n", .{value});
    if (response.allow) |value| try writer.print("Allow: {s}\r\n", .{value});
    if (status != .no_content) try writer.print("Content-Length: {d}\r\n", .{response.body.len});
    try writer.writeAll("Connection: close\r\n\r\n");
    try writer.writeAll(response.body);
    try writer.flush();
}

// ---------------------------------------------------------------- tests

const testing = std.testing;

/// Reads `raw` through a reader whose buffer meets `readBufferLen`.
const TestRead = struct {
    buffer: []u8,
    reader: Io.Reader,
    arena: std.heap.ArenaAllocator,
    result: ReadResult,

    fn init(t: *TestRead, raw: []const u8) !void {
        const limits: Limits = .{};
        t.buffer = try testing.allocator.alloc(u8, limits.readBufferLen());
        @memcpy(t.buffer[0..raw.len], raw);
        t.reader = .fixed(t.buffer);
        t.reader.end = raw.len;
        t.arena = .init(testing.allocator);
        t.result = try readRequest(&t.reader, t.arena.allocator(), testing.allocator, limits);
    }

    fn deinit(t: *TestRead) void {
        if (t.result == .request) testing.allocator.free(t.result.request.body);
        t.arena.deinit();
        testing.allocator.free(t.buffer);
    }
};

fn expectResult(expected: ReadResult, raw: []const u8) !void {
    var t: TestRead = undefined;
    try t.init(raw);
    defer t.deinit();
    try testing.expectEqual(expected, t.result);
}

test "parses a request with a body" {
    var t: TestRead = undefined;
    try t.init("PUT /kv/a HTTP/1.1\r\ncontent-length:  5 \r\nHost: x\r\n\r\nhello");
    defer t.deinit();
    const req = t.result.request;
    try testing.expectEqualStrings("PUT", req.method);
    try testing.expectEqualStrings("/kv/a", req.target);
    try testing.expectEqualStrings("hello", req.body);
}

test "header limit" {
    const limits: Limits = .{};
    const raw = try testing.allocator.alloc(u8, limits.max_header_bytes + 1);
    defer testing.allocator.free(raw);
    @memset(raw, 'a');
    try expectResult(.{ .reject = .request_header_fields_too_large }, raw);
}

test "rejects malformed requests" {
    try expectResult(.{ .reject = .bad_request }, "GET /\r\n\r\n");
    try expectResult(.{ .reject = .bad_request }, " / HTTP/1.1\r\n\r\n");
    try expectResult(.{ .reject = .bad_request }, "GET  HTTP/1.1\r\n\r\n");
    try expectResult(.{ .reject = .bad_request }, "GET / FTP/1.1\r\n\r\n");
    try expectResult(.{ .reject = .http_version_not_supported }, "GET / HTTP/2\r\n\r\n");
    try expectResult(.{ .reject = .bad_request }, "GET / HTTP/1.1\r\nNoColon\r\n\r\n");
    try expectResult(.{ .reject = .bad_request }, "GET / HTTP/1.1\r\n: x\r\n\r\n");
    try expectResult(.{ .reject = .bad_request }, "GET / HTTP/1.1\r\nContent-Length: +1\r\n\r\nx");
    try expectResult(.{ .reject = .bad_request }, "GET / HTTP/1.1\r\nContent-Length: 1_0\r\n\r\nx");
    try expectResult(.{ .reject = .bad_request }, "GET / HTTP/1.1\r\nContent-Length:\r\n\r\n");
    try expectResult(.{ .reject = .bad_request }, "GET / HTTP/1.1\r\nContent-Length: 1\r\nContent-Length: 2\r\n\r\nxx");
    try expectResult(.{ .reject = .not_implemented }, "GET / HTTP/1.1\r\nTransfer-Encoding: chunked\r\n\r\n");
    try expectResult(.{ .reject = .payload_too_large }, "PUT /kv/a HTTP/1.1\r\nContent-Length: 1048577\r\n\r\n");
}

test "truncated input closes" {
    try expectResult(.closed, "GET / HTTP/1.1\r\n");
    try expectResult(.closed, "PUT /kv/a HTTP/1.1\r\nContent-Length: 4\r\n\r\nab");
}

test "writes responses" {
    var buf: [256]u8 = undefined;
    var writer: Io.Writer = .fixed(&buf);
    try writeResponse(&writer, .text(.ok, "ok"));
    try testing.expectEqualStrings(
        "HTTP/1.1 200 OK\r\nContent-Type: text/plain; charset=utf-8\r\nContent-Length: 2\r\nConnection: close\r\n\r\nok",
        writer.buffered(),
    );

    writer = .fixed(&buf);
    try writeResponse(&writer, .empty(.no_content));
    try testing.expectEqualStrings("HTTP/1.1 204 No Content\r\nConnection: close\r\n\r\n", writer.buffered());
}

//! kvhttp: an in-memory HTTP/1.1 key-value server.
//!
//! Usage: app <port>   (listens on 127.0.0.1:<port>)

const std = @import("std");
const Allocator = std.mem.Allocator;
const Io = std.Io;
const net = std.Io.net;
const posix = std.posix;

const http = @import("http.zig");
const KvStore = @import("KvStore.zig");
const Router = @import("Router.zig");

const log = std.log.scoped(.kvhttp);

const limits: http.Limits = .{};

/// Idle/stalled clients are dropped after this long so they cannot pin a
/// thread forever.
const socket_timeout_seconds = 30;

const Server = struct {
    io: Io,
    gpa: Allocator,
    router: Router,
};

pub fn main(init: std.process.Init) !void {
    const io = init.io;
    const gpa = init.gpa;

    const args = try init.minimal.args.toSlice(init.arena.allocator());
    if (args.len != 2) {
        std.debug.print("usage: {s} <port>\n", .{args[0]});
        std.process.exit(2);
    }
    const port = parsePort(args[1]) orelse {
        std.debug.print("invalid port: {s}\n", .{args[1]});
        std.process.exit(2);
    };

    const address: net.IpAddress = .{ .ip4 = .loopback(port) };
    var listener = address.listen(io, .{ .reuse_address = true }) catch |err| {
        std.debug.print("fatal: listen on port {d}: {t}\n", .{ port, err });
        std.process.exit(1);
    };
    defer listener.deinit(io);

    var store: KvStore = .init(gpa);
    defer store.deinit();
    const server: Server = .{ .io = io, .gpa = gpa, .router = .{ .store = &store } };

    // One task per connection: connections are short-lived and the required
    // concurrency is modest.
    var connections: Io.Group = .init;
    defer connections.cancel(io);

    while (true) {
        const stream = listener.accept(io) catch |err| switch (err) {
            error.ConnectionAborted, error.WouldBlock => continue,
            error.ProcessFdQuotaExceeded, error.SystemFdQuotaExceeded, error.SystemResources => {
                try io.sleep(.fromMilliseconds(10), .awake);
                continue;
            },
            else => |e| return e,
        };
        connections.concurrent(io, serveConnection, .{ &server, stream }) catch |err| {
            log.err("failed to spawn handler: {t}", .{err});
            stream.close(io);
        };
    }
}

fn serveConnection(server: *const Server, stream: net.Stream) void {
    const io = server.io;
    const gpa = server.gpa;
    defer stream.close(io);
    configureClient(stream.socket.handle);

    var arena_state: std.heap.ArenaAllocator = .init(gpa);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    respond(server, stream, arena) catch |err| switch (err) {
        error.OutOfMemory => log.err("out of memory while serving a request", .{}),
    };
    // Half-close so the client reads the full response before the FIN.
    stream.shutdown(io, .send) catch {};
}

fn respond(server: *const Server, stream: net.Stream, arena: Allocator) Allocator.Error!void {
    const io = server.io;
    const gpa = server.gpa;

    const read_buffer = try arena.alloc(u8, limits.readBufferLen());
    var reader = stream.reader(io, read_buffer);
    var write_buffer: [4096]u8 = undefined;
    var writer = stream.writer(io, &write_buffer);

    const reply: Router.Reply = reply: switch (try http.readRequest(&reader.interface, arena, gpa, limits)) {
        .closed => return,
        .reject => |status| break :reply .{ .response = .empty(status) },
        .request => |request| {
            var req = request;
            defer gpa.free(req.body);
            break :reply server.router.handle(io, arena, &req) catch
                .{ .response = .empty(.internal_server_error) };
        },
    };
    defer reply.release(gpa);

    http.writeResponse(&writer.interface, reply.response) catch {};
}

fn configureClient(fd: net.Socket.Handle) void {
    const one = std.mem.toBytes(@as(c_int, 1));
    posix.setsockopt(fd, posix.IPPROTO.TCP, posix.TCP.NODELAY, &one) catch {};

    // When these fire, std.Io maps the resulting EAGAIN to error.Unexpected
    // and the connection is dropped.
    const timeout: posix.timeval = .{ .sec = socket_timeout_seconds, .usec = 0 };
    const timeout_bytes = std.mem.asBytes(&timeout);
    posix.setsockopt(fd, posix.SOL.SOCKET, posix.SO.RCVTIMEO, timeout_bytes) catch {};
    posix.setsockopt(fd, posix.SOL.SOCKET, posix.SO.SNDTIMEO, timeout_bytes) catch {};
}

fn parsePort(text: []const u8) ?u16 {
    if (text.len == 0) return null;
    for (text) |c| if (!std.ascii.isDigit(c)) return null;
    const port = std.fmt.parseUnsigned(u16, text, 10) catch return null;
    return if (port == 0) null else port;
}

test parsePort {
    try std.testing.expectEqual(@as(?u16, 8080), parsePort("8080"));
    try std.testing.expectEqual(@as(?u16, 65535), parsePort("65535"));
    try std.testing.expectEqual(@as(?u16, null), parsePort("0"));
    try std.testing.expectEqual(@as(?u16, null), parsePort("65536"));
    try std.testing.expectEqual(@as(?u16, null), parsePort("+80"));
    try std.testing.expectEqual(@as(?u16, null), parsePort(""));
}

